/**
 * [FS-WECHAT-CONSECUTIVE] 微信连发合并窗口。
 *
 * 同一个会话里同一个人连着发的纯文本，先在窗口内攒成一组，到点只走一次 decide：
 * 这一组算「一条主消息」，里面每句都完整进模型，一起理解、一起回，而不是逐条掷概率
 * 造成「回了一句、漏了两句」。图片 / 语音 / 文件 / 合并转发不进缓冲，遇到就先放行
 * 已攒的那组，保证消息顺序不错位。
 *
 * 窗口取 batchMs（默认 800），夹在 2 秒到 8 秒之间：太短合不上连发，太长整个微信都变慢。
 * 窗口不因后续消息重置——按第一条起算，延迟可预期。
 *
 * @returns {boolean} true 表示这条已进缓冲，调用方不要再 decide。
 */
bufferWechatText(m, person, cfg) {
	const wait = Math.max(2000, Math.min(Number(cfg?.batchMs) || 0, 8000));
	this.wechatTextBuf ??= new Map();
	const key = m.channelId;
	const flushKey = () => {
		const buf = this.wechatTextBuf.get(key);
		if (buf === undefined) return;
		this.wechatTextBuf.delete(key);
		if (buf.timer !== null) clearTimeout(buf.timer);
		const items = buf.items;
		const last = items[items.length - 1];
		if (last === undefined) return;
		const merged = { ...last.m };
		if (items.length > 1) {
			merged.text = items.map((x) => String(x.m.text ?? '')).filter((t) => t.trim() !== '').join('\n');
			merged.mentioned = items.some((x) => x.m.mentioned === true);
			// 记下这一组到底几句：下游据此提醒模型「每句都要接」，别再只挑一句回
			merged.batchCount = items.length;
			// 一组里后面有人 @ 过，整组就当点名处理；时间戳取最后一条，别被首条的旧时间误判成过期
			merged.timeMs = last.m.timeMs;
			this.log('info', `[fish-soul][wechat-merge] 合并 ${items.length} 条连发文字一起处理 channel=${key}`);
		}
		Promise.resolve()
			.then(() => this.decide(merged, last.person, this.wechatConfig()))
			.catch((error) => this.log('warn', `[fish-soul][wechat-merge] decide 失败：${String(error)}`));
	};
	const pureText = (m.images ?? []).length === 0 && (m.records ?? []).length === 0
		&& (m.files ?? []).length === 0 && (m.forwards ?? []).length === 0;
	if (!pureText) {
		// 非文本（图片 / 语音 / 文件）先让前面攒的文字走完，再处理自己，顺序不乱
		flushKey();
		return false;
	}
	const buf = this.wechatTextBuf.get(key);
	if (buf !== undefined) {
		buf.items.push({ m, person });
		return true;
	}
	const next = { items: [{ m, person }], timer: null };
	this.wechatTextBuf.set(key, next);
	next.timer = setTimeout(flushKey, wait);
	next.timer.unref?.();
	return true;
}

